func TestOpenTimingAndHalfOpenSingleProbe(t *testing.T) {
	h, nowp := clockHarness()
	now := *nowp
	mustRegisterBreaker(t, h, "svc", "a", 3, 2, 10)

	// Three permits; the first two fail and open the breaker while p3 stays
	// outstanding. Opening never cancels a granted permit.
	p1 := acquireOK(t, h, "svc", acquireBody("k", 300, "")).PermitToken
	p2 := acquireOK(t, h, "svc", acquireBody("k", 300, "")).PermitToken
	p3 := acquireOK(t, h, "svc", acquireBody("k", 300, "")).PermitToken
	for _, tok := range []string{p1, p2} {
		if rec := do(t, h, http.MethodPost, "/v1/admission/svc/permits/"+tok+"/complete", `{"outcome":"failure"}`, nil); rec.Code != http.StatusNoContent {
			t.Fatalf("complete = %d", rec.Code)
		}
	}
	expectBlocked := func() {
		t.Helper()
		rec := doAcquire(t, h, "svc", acquireBody("k", 60, ""))
		if rec.Code != http.StatusServiceUnavailable || errorCode(t, rec) != "circuit_open" {
			t.Fatalf("acquire = %d (%s), want 503 circuit_open", rec.Code, errorCode(t, rec))
		}
	}
	expectBlocked()
	// The outstanding ordinary permit can still be completed or released.
	if rec := do(t, h, http.MethodPost, "/v1/admission/svc/permits/"+p3+"/complete", `{"outcome":"failure"}`, nil); rec.Code != http.StatusNoContent {
		t.Fatalf("complete during open = %d, want 204", rec.Code)
	}

	now = now.Add(9 * time.Second)
	expectBlocked()
	now = now.Add(1 * time.Second) // openSeconds elapsed -> half_open

	probe := acquireOK(t, h, "svc", acquireBody("k", 60, ""))
	// Exactly one trial permit: a second acquire is breaker-blocked.
	expectBlocked()

	// A trial success closes the breaker and clears the failure streak.
	if rec := do(t, h, http.MethodPost, "/v1/admission/svc/permits/"+probe.PermitToken+"/complete", `{"outcome":"success"}`, nil); rec.Code != http.StatusNoContent {
		t.Fatalf("probe complete = %d", rec.Code)
	}
	acquireOK(t, h, "svc", acquireBody("k", 60, ""))
	// Counter was reset: a single failure below the threshold of two must
	// not reopen.
	tok := acquireOK(t, h, "svc", acquireBody("k", 60, "")).PermitToken
	if rec := do(t, h, http.MethodPost, "/v1/admission/svc/permits/"+tok+"/complete", `{"outcome":"failure"}`, nil); rec.Code != http.StatusNoContent {
		t.Fatalf("complete = %d", rec.Code)
	}
	acquireOK(t, h, "svc", acquireBody("k", 60, ""))
	*nowp = now
}

