		}
		expectCircuitOpen(t, h, acquireBody("k", 60, ""))
		advance(now, 10*time.Second)
		acquireOK(t, h, "svc", acquireBody("k", 60, "")) // fresh period elapsed
	})

	t.Run("expire", func(t *testing.T) {
		h, now := clockHarness()
