	}
	if rec := completePermit(t, h, "svc", other, "failure"); rec.Code != http.StatusNotFound {
		t.Fatalf("old permit complete = %d, want 404", rec.Code)
	}
	acquireOK(t, h, "svc", acquireBody("k", 60, ""))
}

